-- =====================
-- SPRITES / TILES
-- =====================
SPR_PLAYER = 256
SPR_BUMPER = 257

-- setting wall tiles as solid
SOLID_TILES = {
 [1]=true,[2]=true,[3]=true,[4]=true,[5]=true,[6]=true,[7]=true,
 [8]=true,[9]=true,[10]=true,[11]=true,[12]=true,[13]=true
}

-- =====================
-- CONSTANTS
-- =====================
ROOM_W = 240
ROOM_H = 136
TILE = 8
GRAVITY = 0.02
PLAYER_W = 8
PLAYER_H = 8
NUM_ROOMS = 9

-- Horizontal movement constants
H_ACCEL    = 0.25
H_FRICTION = 0.90
MAX_HSPEED = 2.0

-- Bumper physics
BUMPER_RADIUS = 4
BOUNCE_STRENGTH = 2.5

-- =====================
-- PLAYER STATE
-- =====================
px, py = 0, 0
vx, vy = 0, 0
on_ground = false

-- =====================
-- GAME STATE
-- =====================
current_room = 1
active_bumpers = {}
game_over = false
show_title = true
title_timer = 300 -- 5 seconds

-- =====================
-- ROOM DATA (starting positions)
-- =====================
ROOMS = {
    { start_x = 14*TILE, start_y = 1*TILE }, -- room 1
    { start_x = 20*TILE, start_y = 2*TILE }, -- room 2
    { start_x = 16*TILE, start_y = 2*TILE }, -- room 3
    { start_x = 14*TILE, start_y = 1*TILE }, -- room 4
    { start_x = 20*TILE, start_y = 2*TILE }, -- room 5
    { start_x = 16*TILE, start_y = 2*TILE }, -- room 6
    { start_x = 14*TILE, start_y = 1*TILE }, -- room 7
    { start_x = 20*TILE, start_y = 2*TILE }, -- room 8
    { start_x = 16*TILE, start_y = 2*TILE }, -- room 9
}

-- =====================
-- ROOM BUMPERS (world coordinates)
-- =====================
BUMPERS = {
    [4] = {
        {x=10*TILE, y=5*TILE}, {x=10*TILE, y=13*TILE}, {x=8*TILE, y=9*TILE},
        {x=14*TILE, y=9*TILE}, {x=20*TILE, y=9*TILE}, {x=19*TILE, y=5*TILE},
        {x=19*TILE, y=13*TILE},
    },
    [5] = {
        {x=50*TILE, y=4*TILE}, {x=44*TILE, y=11*TILE},
    },
    [7] = {
        {x=12*TILE, y=4*TILE}, {x=10*TILE, y=7*TILE}, {x=8*TILE, y=8*TILE},
        {x=8*TILE, y=9*TILE}, {x=8*TILE, y=10*TILE}, {x=10*TILE, y=12*TILE},
        {x=12*TILE, y=14*TILE}, {x=16*TILE, y=4*TILE}, {x=14*TILE, y=7*TILE},{x=16*TILE, y=14*TILE},
    },
    [8] = {
        {x=50*TILE, y=4*TILE}, {x=41*TILE, y=8*TILE}, {x=44*TILE, y=12*TILE},
    },
    [9] = {
        {x=68*TILE, y=5*TILE}, {x=68*TILE, y=11*TILE}, {x=76*TILE, y=13*TILE},
    },
}

-- =====================
-- MAKE COLOR 0 (BLACK) TRANSPARENT
-- =====================
poke(0x3FFB, 0)

-- =====================
-- LOAD ROOM
-- =====================
function load_room(n)
    local room = ROOMS[n]
    if not room then return end

    -- Player starts at room's start position
    px = room.start_x or 0
    py = room.start_y or 0
    vx, vy = 0, 0

    -- Load bumpers for this room
    active_bumpers = BUMPERS[n] or {}
end

-- =====================
-- COLLISION HELPERS
-- =====================
function solid_at(x,y)
    local tx = math.floor(x/TILE)
    local ty = math.floor(y/TILE)
    return SOLID_TILES[mget(tx, ty)] == true
end

function hit(ax,ay,aw,ah,bx,by,bw,bh)
    return ax<bx+bw and ax+aw>bx and ay<by+bh and ay+ah>by
end

-- =====================
-- PLAYER UPDATE
-- =====================
function update_player()
    -- Horizontal movement
    if btn(2) then vx = vx - H_ACCEL end
    if btn(3) then vx = vx + H_ACCEL end

    if vx > MAX_HSPEED then vx = MAX_HSPEED end
    if vx < -MAX_HSPEED then vx = -MAX_HSPEED end
    vx = vx * H_FRICTION
    px = px + vx

    -- Vertical physics
    vy = vy + GRAVITY
    py = py + vy

    -- Floor collision
    local bottom = py + PLAYER_H
    if solid_at(px+1,bottom) or solid_at(px+PLAYER_W/2,bottom) or solid_at(px+PLAYER_W-1,bottom) then
        py = math.floor(bottom/TILE)*TILE - PLAYER_H
        vy = 0
        on_ground = true
    else
        on_ground = false
    end

    -- Screen bounds
    if px < 0 then px=0; vx=0 end
    if px + PLAYER_W > ROOM_W then px=ROOM_W-PLAYER_W; vx=0 end

    -- Game over on solid tiles
    for dx=0,PLAYER_W-1 do
        for dy=0,PLAYER_H-1 do
            if SOLID_TILES[mget(math.floor((px+dx)/TILE), math.floor((py+dy)/TILE))] then
                game_over=true
            end
        end
    end

    -- Pinball bumpers
    local cx, cy = px + PLAYER_W/2, py + PLAYER_H/2
    for _,b in ipairs(active_bumpers) do
        local dx, dy = cx - b.x, cy - b.y
        local dist = math.sqrt(dx*dx + dy*dy)
        if dist < BUMPER_RADIUS + PLAYER_W/2 and dist > 0 then
            local nx, ny = dx/dist, dy/dist
            vx = nx * BOUNCE_STRENGTH
            vy = ny * BOUNCE_STRENGTH
        end
    end
end

-- =====================
-- DRAW FUNCTIONS
-- =====================
function draw_player()
    spr(SPR_PLAYER, px, py)
end

function draw_bumper()
    for _,b in ipairs(active_bumpers) do
        spr(SPR_BUMPER, b.x, b.y)
    end
end

-- =====================
-- MAIN LOOP
-- =====================
function TIC()
    -- Title / Notice
    if show_title then
        cls(0)
        print("Copyright (C) 2025 Daniel",0,10,12,false,1,true)
        print("Hanrahan Tools and Games",0,20,12,false,1,true)
        print("SPDX-License-Identifier: GPL-3.0-or-later",0,30,12,false,1,true)
        print("A copy of the GNU General Public License is",0,40,12,false,1,true)
        print("included in the file COPYING; if not, see",0,50,12,false,1,true)
        print("<https://www.gnu.org/licenses/>.",0,60,12,false,1,true)
        print("Information just about the stuff in this",0,70,12,false,1,true)
        print("software not covered by the GNU General",0,80,12,false,1,true)
        print("Public License version 3: This work is",0,90,12,false,1,true)
        print("licensed under Attribution-ShareAlike",0,100,12,false,1,true)
        print("4.0 International",0,110,12,false,1,true)
        print("PRESS Z TO START",80,120,12,false,1,true)

        title_timer = title_timer - 1
        if title_timer <=0 or btnp(4) then
            show_title=false
            current_room=math.random(NUM_ROOMS)
            load_room(current_room)
        end
        return
    end

    -- Game over screen
    if game_over then
        cls(0)
        print("GAME OVER",90,60,12)
        print("PRESS Z TO RESTART",50,80,14)
        if btnp(4) then
            game_over=false
            current_room=math.random(NUM_ROOMS)
            load_room(current_room)
        end
        return
    end

    -- Main game loop
    cls(0)
    map((current_room-1)*30,0,30,17,0,0)

    update_player()
    draw_bumper()
    draw_player()

    -- Room transition if marble reaches bottom
    if py + PLAYER_H >= ROOM_H then
        local next_room
        repeat
            next_room = math.random(NUM_ROOMS)
        until next_room ~= current_room
        current_room = next_room
        load_room(current_room)
    end
end

